import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788526325000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>All configuration is by environment variable; there is no config file.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>IMAP_HOST</code></td><td>yes</td><td>—</td><td>Hostname of the IMAP server, e.g. <code>imap.example.net</code></td></tr><tr><td><code>IMAP_USER</code></td><td>yes</td><td>—</td><td>Mailbox user name</td></tr><tr><td><code>IMAP_PASSWORD</code></td><td>yes</td><td>—</td><td>Mailbox password, or an app password where the provider offers one</td></tr><tr><td><code>IMAP_PORT</code></td><td>no</td><td>993 or 143</td><td>993 with implicit TLS, 143 otherwise</td></tr><tr><td><code>IMAP_TLS</code></td><td>no</td><td><code>implicit</code></td><td><code>implicit</code>, <code>starttls</code> or <code>none</code></td></tr><tr><td><code>IMAP_MAILBOX</code></td><td>no</td><td><code>INBOX</code></td><td>The mailbox the tools work in unless one is named</td></tr><tr><td><code>IMAP_SEEN_KEYWORD</code></td><td>no</td><td><code>AiSeen</code></td><td>IMAP keyword marking what the assistant has already seen</td></tr><tr><td><code>IMAP_READ_ONLY</code></td><td>no</td><td><strong><code>true</code></strong></td><td><code>false</code> registers the mailbox write tools. Note the default</td></tr><tr><td><code>IMAP_ALLOW_TOOLS</code></td><td>no</td><td>—</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>IMAP_DENY_TOOLS</code></td><td>no</td><td>—</td><td>Same syntax; subtracted from whatever the allow list left</td></tr><tr><td><code>IMAP_DOWNLOAD_DIR</code></td><td>no</td><td>—</td><td>Where attachments may be written. Unset means the filesystem is never touched</td></tr><tr><td><code>IMAP_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, scoped to this connection</td></tr><tr><td><code>IMAP_TRUSTED_AUTHSERV_ID</code></td><td>no</td><td>—</td><td>The authserv-id your provider stamps; without it every verdict is forgeable</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><p>There are also <code>IMAP_MAX_MESSAGES</code>, <code>IMAP_MAX_ATTACHMENT_BYTES</code>, <code>IMAP_MAX_DOWNLOAD_BYTES</code>, <code>IMAP_MAX_EXTRACT_BYTES</code> and <code>IMAP_DRAFTS_MAILBOX</code> for the limits and the drafts folder; the defaults are 100 messages, 1 MB inline, 25 MB to disk, 10 MB into the text extractor, and whichever folder the server flags as <code>\\Drafts</code>.</p><p>The three size limits are separate because they answer three different questions. <code>IMAP_MAX_ATTACHMENT_BYTES</code> bounds what may enter the model&#39;s context; <code>IMAP_MAX_DOWNLOAD_BYTES</code> bounds what may be written to your disk; <code>IMAP_MAX_EXTRACT_BYTES</code> bounds how much input one parser is handed, which is a memory question and neither of the other two. Raising one is not a request to raise the others. <code>IMAP_MAX_EXTRACT_BYTES</code> is the one with a hard ceiling — 64 MB — and a value above it refuses to start rather than being clamped: the other two buy a big answer, this one buys a buffer inside a parser working on bytes a stranger chose, so a typo there would leave you believing there is a limit.</p><h2 id="imap-trusted-authserv-id-and-the-forgeable-flag" tabindex="-1"><code>IMAP_TRUSTED_AUTHSERV_ID</code> and the <code>forgeable</code> flag <a class="header-anchor" href="#imap-trusted-authserv-id-and-the-forgeable-flag" aria-label="Permalink to “IMAP_TRUSTED_AUTHSERV_ID and the forgeable flag”">​</a></h2><p><code>get_message</code> reports the SPF, DKIM and DMARC verdicts from the message&#39;s <code>Authentication-Results</code> header, together with a <code>forgeable</code> flag. By default that flag is always <code>true</code>, and that is not a bug.</p><p>Anyone can put an <code>Authentication-Results</code> header in a message they send. Your provider normally adds its own and prepends it, so reading only the topmost header ignores a forged copy underneath — but if your provider adds none at all, which is common on small Postfix/Dovecot setups and on any mailbox where filtering happens somewhere else, the sender&#39;s header is the topmost one. Nothing inside the message tells the two apart.</p><p>Set this to the id your provider stamps and only that id is treated as authentic:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">IMAP_TRUSTED_AUTHSERV_ID</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">mx.example.net</span></span></code></pre></div><p>It is the first token of the header, before the first semicolon. Open any message you already trust and read it off. The comparison is case-insensitive and exact — a subdomain of the configured id does not match, because <code>evil.mx.example.net</code> is a different host and a sender can choose it.</p><div class="tip custom-block"><p class="custom-block-title">Why not guess it</p><p>An earlier version compared the authserv-id against your own account&#39;s domain and called a match authentic. A sender knows your domain — they just addressed mail to you — so <code>Authentication-Results: mail.yourdomain.example; spf=pass; dkim=pass</code> was enough to have this server vouch for a spoofed message. The heuristic gave its strongest answer in exactly the case it could not verify.</p></div><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before <code>delete_messages</code>, <code>move_messages</code> or deleting a folder acts. Default <code>true</code>. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Like <code>IMAP_TLS</code>, and unlike <code>IMAP_READ_ONLY</code>: <code>1</code>, <code>off</code> or a typo stop the server with exit code 1. It is the only variable of this family that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em><code>IMAP_PASSWORD</code> is deleted from <code>process.env</code>, so the fatal path cannot leave the password sitting there for a crash reporter.</p><h2 id="imap-read-only-defaults-to-true" tabindex="-1"><code>IMAP_READ_ONLY</code> defaults to <code>true</code> <a class="header-anchor" href="#imap-read-only-defaults-to-true" aria-label="Permalink to “IMAP_READ_ONLY defaults to true”">​</a></h2><p>This is the one place this server differs from the rest of the family, and it is deliberate. Everywhere else <code>&lt;PREFIX&gt;_READ_ONLY</code> defaults to <code>false</code> and you switch it on. Here the variable replaced <code>IMAP_ALLOW_WRITE</code>, which was <strong>opt-in</strong> — setting nothing meant no write access to a mailbox. Renaming it without keeping that default would have handed write access to every installation that upgraded without reading the changelog.</p><p>Only the literal string <code>false</code> turns it off. <code>False</code>, <code>0</code> and <code>no</code> all leave the write tools unregistered, so a typo fails closed.</p><div class="danger custom-block"><p class="custom-block-title">IMAP_ALLOW_WRITE is gone</p><p>An installation that still sets it <strong>will not start</strong>. Silently ignoring a removed security variable is worse than refusing: whoever set it once believes it is still in force. Set <code>IMAP_READ_ONLY=false</code> instead, or unset it and keep the read-only default.</p></div><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><p><code>IMAP_ALLOW_TOOLS</code> and <code>IMAP_DENY_TOOLS</code> are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Registers</th></tr></thead><tbody><tr><td><code>essential</code></td><td>the curated six, marked in the <a href="/reference/tools">tool reference</a></td></tr><tr><td><code>list_new_messages,get_message</code></td><td>exactly those two</td></tr><tr><td><code>list_*</code></td><td><code>list_mailboxes</code>, <code>list_messages</code>, <code>list_new_messages</code></td></tr><tr><td><code>essential,get_attachments</code></td><td>the preset plus one more</td></tr><tr><td><code>*</code></td><td>everything — the same as leaving it unset</td></tr></tbody></table><p>Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>IMAP_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_messages</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under the read-only default, an exact write-tool name in the allow list is an error naming <code>IMAP_READ_ONLY</code> rather than &quot;unknown tool&quot; — which matters more here than elsewhere, because read-only is the default rather than something you remember switching on. A pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p><h2 id="what-the-filter-does-not-cover" tabindex="-1">What the filter does not cover <a class="header-anchor" href="#what-the-filter-does-not-cover" aria-label="Permalink to “What the filter does not cover”">​</a></h2><p>Tools. This server also exposes <strong>attachment resources</strong>, and those are not filtered: <code>IMAP_ALLOW_TOOLS</code> narrows <code>tools/list</code>, not <code>resources/list</code>. <code>IMAP_DOWNLOAD_DIR</code> and the attachment type allowlist are what constrain those.</p><h2 id="credentials-in-the-environment" tabindex="-1">Credentials in the environment <a class="header-anchor" href="#credentials-in-the-environment" aria-label="Permalink to “Credentials in the environment”">​</a></h2><p><code>IMAP_PASSWORD</code> is read once and then deleted from <code>process.env</code>, so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>, and a later crash report cannot carry it.</p>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};